// Open Deploy: the door's one entry, and the only place it names itself. The webhook is now the
// ONLY way in (Operator ruling 2026-09-03): the daily feed lives in Airtable, as Schedule Live
// View Deploys, which creates the launch rows and fires this webhook, so the scheduled and the
// on-demand path are the same path by construction instead of by convention.
const b = ($input.first() || {}).json || {};
const recordId = String((b.body && b.body.recordId) || (b.query && b.query.recordId) || b.recordId || '').trim();
return [{ json: {
  mode: 'prepare',
  sender: 'Alta',
  automation: 'Deploy View to Alta Campaign',
  execId: String($execution.id),
  wfId: String($workflow.id),
  recordId: recordId || 'recMISSING'
} }];

// Load State: what prepare resolved becomes this run's state, and its pushes become one item each,
// because Alta takes one prospect per request. The state also goes into static data for the nodes
// before the wait; everything after it restores from the item Collect Push carries, since static
// data does not survive a 90-second Wait resume (two runs died exactly there, 2026-08-31 and
// 2026-09-01).
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
const p = ($input.first() || {}).json || {};
const D = p.state || {};
sd[dk] = D;
const pushes = Array.isArray(p.pushes) ? p.pushes : [];
if (!p.ready || !pushes.length) return [{ json: { _none: true } }];
return pushes.map(x => ({ json: x }));

// Collect Push: the pull-in responses, per prospect. Alta answers 200 even for pushes it later
// drops (a paused campaign swallows pull-ins silently, proven live 2026-08-27), so a 200 here
// counts only as "sent"; landing is decided by the readback, never by this response.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id; const D = sd[dk];
let sent = 0, failed = 0;
const items = $input.all();
const pushed = [];
try { for (const it of $('Load State').all()) { const j = it.json || {}; if (j.recordId) pushed.push(j.recordId); } } catch (e) {}
items.forEach((it, i) => {
  const j = it.json || {};
  const status = Number(j.statusCode) || ((j.error) ? 0 : 200);
  const rid = pushed[i];
  if (status >= 200 && status < 300) { sent++; }
  else { failed++; if (rid && D.rows[rid]) D.rows[rid].skip = 'push failed HTTP ' + status; }
});
D.pushed = sent;
if (failed) D.warnings.push(failed + ' pull-in push(es) failed with a non-2xx status');
// The whole run state rides this item across RB Wait. A Wait node suspends and resumes the
// execution, and workflow static data does NOT survive the resume; node output data does, so
// every post-wait node restores the state from here when it wakes up empty.
return [{ json: { sent, failed, campaignId: D.target, _state: D } }];

// Verify Landing: the campaign's live prospect list after the pushes. Alta's pull-in answers
// 200 and can still drop the prospect (paused campaign, proven 2026-08-27), so landing is
// decided HERE by values. Fresh prospects (created since run start) are the primary
// candidates; if pushed rows remain unaccounted for, the WHOLE membership is resolved
// (capped) so a row that landed in an earlier crashed run is recognized and STAMPED instead
// of being re-pushed every day forever - the crash-hole closed 2026-08-31.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
// Static data does not survive the RB Wait resume; restore from the state Collect Push carried.
let D=sd[dk]; if(!D){ try{ D=$('Collect Push').first().json._state; }catch(e){} if(D) sd[dk]=D; }
// No state to read means no landing can be decided; Close Deploy owns the recovery and the row.
if(!D||D.abort){ return [{json:{_none:true, personIds:[]}}]; }
let rows=[];
try{ const j=($input.first()||{}).json||{}; rows=Array.isArray(j.rows)?j.rows:[]; }catch(e){}
D.campaignProspects=rows.length;
const since=new Date((D.startedAt||Date.now())-10*60*1000).toISOString();
D.freshProspects={};
const freshIds=[]; const oldIds=[];
for(const p of rows){
  if(!p.personId) continue;
  if(String(p.createdAt||'')>=since){ D.freshProspects[p.personId]={prospectId:p.prospectId}; freshIds.push(p.personId); }
  else oldIds.push(p.personId);
}
let personIds=freshIds.slice(0,300);
// Pushed more than fresh accounts for? A prior run may have landed rows it never stamped.
if(D.pushed>freshIds.length&&oldIds.length){
  D.fallbackUsed=true;
  personIds=personIds.concat(oldIds.slice(0,Math.max(0,500-personIds.length)));
  D.warnings.push('pushed '+D.pushed+' but only '+freshIds.length+' fresh prospects; resolving '+Math.min(oldIds.length,500-freshIds.length)+' older members to heal unstamped landings');
}
if(freshIds.length>300) D.warnings.push('readback capped at 300 fresh prospects of '+freshIds.length);
if(!personIds.length){
  if(D.pushed) D.warnings.push('pushed '+D.pushed+' but the campaign shows no prospects at all; Alta may have dropped them (is the campaign paused?)');
  return [{json:{_none:true, personIds:[]}}];
}
return [{json:{personIds}}];

// Title Gate: Alta's OWN enriched person data against the buyer rule, after landing. Alta
// stores its own title for a person, and it can disagree with ours; nothing that checks only
// our side can catch that (the Lewin Joey incident, 2026-08-27). The rule here mirrors the
// `relevance` formula on the intent tables; a landed prospect whose Alta-side title fails it
// is paused by the next node before a message can go out, and named in the run log.
// Identity too: a person whose Alta LinkedIn URL is not the URL we pushed is paused.
const sd=$getWorkflowStaticData('global'); const dk='deploy_'+$execution.id;
// Static data does not survive the RB Wait resume; restore from the state Collect Push carried.
let D=sd[dk]; if(!D){ try{ D=$('Collect Push').first().json._state; }catch(e){} if(D) sd[dk]=D; }
// No state to read means nothing can be judged; Close Deploy owns the recovery and the row.
if(!D||D.abort){ return [{json:{prospectIds:[], action:'pause', _none:true}}]; }
let persons=[];
try{ const j=($input.first()||{}).json||{}; persons=Array.isArray(j.rows)?j.rows:[]; }catch(e){}
const normUrl=u=>String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/+$/,'').split('?')[0];
const roleOnly=t=>{ let s=String(t||''); s=s.split(/\s+\|\s+|\s+@\s+/)[0]; s=s.replace(/\s+at\s+[^|]*$/i,''); return s.trim(); };
const EXEC=/\b(founder|founding|co-?founder|owner|ceo|cto|cio|ciso|coo|president|chief)\b/i;
const LEAD=/\b(vp|svp|evp|vice president|head|director|manager|lead|principal|staff)\b/i;
const TECH=/\b(engineering|engineer|technology|technical|infrastructure|infra|platform|devops|sre|site reliability|cloud|security|information security|it|software|systems|architecture|architect|data|product)\b/i;
const IC=/\b(devops|site reliability|sre|platform engineer|infrastructure engineer|cloud engineer|systems engineer|production engineer|release engineer|founding engineer)\b/i;
const STANDALONE=/^(managing director|executive director|senior director|director|partner)$/i;
const NEVER=/\b(marketing|sales|growth|revenue|people|talent|recruiting|recruiter|hr|human resources|finance|financial|accounting|brand|content|community|customer|client|account|assistant|product owner|chief of staff|mechanical|facilities|contracts|capture|alliances|legal|gis|writer|veteran|medical|clinical|program|managed services|creative|design|designer|gtm|partnerships|strategy|staffing)\b/i;
const passes=(title)=>{ const t=roleOnly(title); if(!t) return false; if(NEVER.test(t)) return false; return EXEC.test(t)||(LEAD.test(t)&&TECH.test(t))||IC.test(t)||STANDALONE.test(t.trim()); };
const pause=[]; const pausedNames=[];
let landed=0, titleFail=0, urlMismatch=0, noData=0;
for(const p of persons){
  const fp=D.freshProspects[p.personId];
  const url=normUrl(p.linkedinUrl);
  const rowId=url?D.urlToRow[url]:'';
  if(!fp){
    // An older member matching a row we just pushed: it landed in a prior run and was never
    // stamped. Stamp it now; never pause old actives here (the standing audit owns them).
    if(rowId&&D.rows[rowId]&&!D.rows[rowId].skip&&!D.rows[rowId].landed){ landed++; D.rows[rowId].landed=true; D.rows[rowId].healed=true; }
    continue;
  }
  if(!p.name&&!p.linkedinUrl){ noData++; pause.push(fp.prospectId); pausedNames.push((p.personId||'?')+' (no person data)'); continue; }
  if(!rowId){ urlMismatch++; pause.push(fp.prospectId); pausedNames.push((p.name||url||'?')+' (URL not one we pushed)'); continue; }
  if(!passes(p.title)){ titleFail++; pause.push(fp.prospectId); pausedNames.push((p.name||'?')+' ('+(roleOnly(p.title)||'no title')+')'); if(D.rows[rowId]) D.rows[rowId].skip='paused: Alta-side title failed the buyer rule'; continue; }
  landed++;
  if(D.rows[rowId]) D.rows[rowId].landed=true;
}
D.landed=landed; D.pausedTitle=titleFail; D.pausedUrl=urlMismatch; D.pausedNoData=noData; D.pausedNames=pausedNames.slice(0,25);
// Rows pushed but not matched by any fresh person: not landed.
let sentNoLand=0;
for(const id of Object.keys(D.rows)){ const rec=D.rows[id]; if(!rec.skip&&!rec.landed){ rec.skip='not in campaign after deploy'; sentNoLand++; } }
D.missing=sentNoLand;
if(!pause.length) return [{json:{_none:true, prospectIds:[], action:'pause'}}];
return [{json:{prospectIds:pause, action:'pause'}}];

// Close Deploy: the push lane is over; everything it learned goes back to the shared machine,
// which stamps the source rows, writes the receipt and writes the run's Hub row.
// Three ways in: no prospects to push at all (static data still intact, the wait was never
// crossed), no persons to verify, and the full path through the title gate. After the wait the
// state comes off the item Collect Push carried, never off static data.
const sd = $getWorkflowStaticData('global'); const dk = 'deploy_' + $execution.id;
let D = sd[dk];
if (!D) { try { D = $('Collect Push').first().json._state; } catch (e) {} }
if (!D) {
  try { D = $('Prepare').first().json.state; } catch (e) {}
  if (D) D.errors.push('run state was lost after the readback wait and was rebuilt from what prepare returned; push and landing counts for this run are not trustworthy');
}
if (!D) throw new Error('Deploy View to Alta Campaign lost its run state entirely; nothing can be stamped or logged for this run.');
delete sd[dk];
return [{ json: {
  mode: 'finish',
  sender: 'Alta',
  automation: 'Deploy View to Alta Campaign',
  execId: String($execution.id),
  wfId: String($workflow.id),
  state: D
} }];
